# LoRA implementation
class LoRALinear:
    def __init__(self, base, rank=8):
        self.base = base
        self.A = random_matrix(rank, base.in_dim)
        self.B = random_matrix(base.out_dim, rank)
        # base.weights are trainable
        self.base.weights.requires_grad = True

    def forward(self, x):
        return self.base(x) + x @ self.A.T @ self.B.T
